# === Metrics history (run-over-run regression tracking) ====================
# Append one JSON line per live run to `metrics_history.jsonl` capturing the
# build/config/key metrics so we can spot regressions across versions.
# Added 2026-06-19 after a Stretch+hedge ship was reverted because the live
# full-period MaxDD blew out from -20.5% to -34.4% without my noticing — the
# sweep-mean MaxDD looked fine in isolation but full-period peak-to-trough
# was much worse. Without a persistent log, that kind of regression is
# invisible run-to-run.
def _evaluate_sweep_result(
    baseline: dict,
    treatment: dict,
    *,
    sharpe_threshold: float = -0.10,
    maxdd_threshold: float = -0.05,
    alpha_threshold: float = -0.01,
    return_threshold: float = -0.01,
    label_baseline: str = "baseline",
    label_treatment: str = "treatment",
) -> dict:
    """Honest verdict for any A/B sweep: treatment vs baseline.

    Each dict should contain: sharpe, max_drawdown, alpha_vs_spy, ann_return.
    Missing keys are treated as 'unmeasured' (skipped). The verdict requires
    treatment NOT to regress materially on ANY of the four dimensions —
    fixes the 2026-06-19 bug where sweep verdicts said PROCEED based on
    Sharpe improvement while silently ignoring a -5.5%/yr return collapse.

    Thresholds are *worst tolerable delta* (negative = regression). Defaults:
      sharpe   ≥ -0.10  (Sharpe must not drop by more than 0.10)
      maxdd    ≥ -0.05  (MaxDD must not deepen by more than 5pp)
      alpha    ≥ -0.01  (alpha vs SPY must not drop by more than 1pp)
      return   ≥ -0.01  (annualised return must not drop by more than 1pp)

    Returns dict with:
      warnings   list[str]  — one line per regressing dimension
      improvements list[str] — one line per materially improving dimension
      verdict    str        — 'SHIP' / 'NEUTRAL' / 'REVERT'
      summary    str        — one-line headline
    """
    def _d(key, neg_is_bad=False):
        b = baseline.get(key); t = treatment.get(key)
        if b is None or t is None:
            return None, None, None
        delta = t - b
        return b, t, delta

    warnings = []
    improvements = []

    b_sh, t_sh, d_sh = _d("sharpe")
    if d_sh is not None:
        if d_sh <= sharpe_threshold:
            warnings.append(f"Sharpe regressed {d_sh:+.3f} ({b_sh:.2f} → {t_sh:.2f})")
        elif d_sh >= -sharpe_threshold:
            improvements.append(f"Sharpe improved {d_sh:+.3f} ({b_sh:.2f} → {t_sh:.2f})")

    b_dd, t_dd, d_dd = _d("max_drawdown")
    if d_dd is not None:
        # max_drawdown is negative; "regressed" = MORE negative (deeper)
        if d_dd <= maxdd_threshold:
            warnings.append(f"MaxDD deepened by {d_dd*100:+.2f}pp "
                              f"({b_dd*100:+.2f}% → {t_dd*100:+.2f}%)")
        elif d_dd >= -maxdd_threshold:
            improvements.append(f"MaxDD improved by {d_dd*100:+.2f}pp "
                                  f"({b_dd*100:+.2f}% → {t_dd*100:+.2f}%)")

    b_al, t_al, d_al = _d("alpha_vs_spy")
    if d_al is not None:
        if d_al <= alpha_threshold:
            warnings.append(f"Alpha vs SPY worsened {d_al*100:+.2f}pp "
                              f"({b_al*100:+.2f}% → {t_al*100:+.2f}%)")
        elif d_al >= -alpha_threshold:
            improvements.append(f"Alpha improved {d_al*100:+.2f}pp "
                                  f"({b_al*100:+.2f}% → {t_al*100:+.2f}%)")

    b_rt, t_rt, d_rt = _d("ann_return")
    if d_rt is not None:
        if d_rt <= return_threshold:
            warnings.append(f"Ann return dropped {d_rt*100:+.2f}pp "
                              f"({b_rt*100:+.2f}% → {t_rt*100:+.2f}%)")
        elif d_rt >= -return_threshold:
            improvements.append(f"Ann return rose {d_rt*100:+.2f}pp "
                                  f"({b_rt*100:+.2f}% → {t_rt*100:+.2f}%)")

    # Overall verdict
    if warnings:
        verdict = "REVERT"
        summary = (f"{label_treatment} regresses on {len(warnings)} dimension(s) "
                    f"vs {label_baseline} — DO NOT SHIP without addressing the warnings")
    elif improvements:
        verdict = "SHIP"
        summary = (f"{label_treatment} improves on {len(improvements)} dimension(s) "
                    f"vs {label_baseline} with no material regression — candidate for shipping")
    else:
        verdict = "NEUTRAL"
        summary = (f"{label_treatment} is within noise of {label_baseline} on all "
                    f"dimensions — no material change, keep current default")

    return {
        "warnings": warnings,
        "improvements": improvements,
        "verdict": verdict,
        "summary": summary,
    }


def _print_sweep_verdict(eval_result: dict) -> None:
    """Pretty-print the result of _evaluate_sweep_result() to console + run.log.
    Always prints warnings FIRST so the eye catches regressions immediately,
    then improvements, then the overall verdict header."""
    print("=" * 88)
    print(f"VERDICT — {eval_result['verdict']}")
    print("=" * 88)
    print(f"  {eval_result['summary']}")
    if eval_result["warnings"]:
        print(f"\n  REGRESSIONS (worst-tolerable thresholds breached):")
        for w in eval_result["warnings"]:
            print(f"    ✗  {w}")
    if eval_result["improvements"]:
        print(f"\n  Improvements (beyond noise):")
        for im in eval_result["improvements"]:
            print(f"    ✓  {im}")
    if not eval_result["warnings"] and not eval_result["improvements"]:
        print(f"  All four dimensions (Sharpe, MaxDD, Alpha, Ann Return) within noise.")


def _append_metrics_snapshot(metrics_table, ensemble_mix_live, w_ensemble_live,
                              tlh_events_n: int = 0, tlh_loss_aud: float = 0.0,
                              n_executed: int = 0, n_skipped: int = 0,
                              scale_metrics: dict | None = None) -> None:
    """Append a metrics snapshot to metrics_history.jsonl + warn on regressions.

    Captures git_sha + build_time + PRODUCTION_* config + 3Y/5Y/10Y Strategy
    Sharpe/MaxDD/Alpha/AnnReturn (and SPY benchmark). Compares to the prior
    snapshot and prints [metrics-warn] lines if 10Y Sharpe regressed by
    ≥0.10, MaxDD deepened by ≥5%, or alpha worsened by ≥1%. Non-fatal —
    purely diagnostic.

    Optional `scale_metrics`: dict keyed by NAV_aud (float) → DataFrame
    of OOS metrics at that NAV (output of compute_oos_metrics on the
    scale-sensitivity backtests). When provided, the per-NAV Strategy
    rows for 3Y/5Y/10Y get nested under a `per_nav_horizons` field so
    metrics_history.jsonl accumulates a continuous track at every scale
    in parallel — used for the wholesale-fund pitch evidence narrative
    (user can answer "what was the Sharpe at $1M six months ago?"
    without re-running the backtest).
    """
    try:
        if metrics_table is None or metrics_table.empty:
            print("[metrics] snapshot skipped — empty metrics_table")
            return
        # Resolve git SHA / build time from the build stamp module if frozen,
        # else fall back to git command on the source tree.
        gsha, btime = "unknown", "unknown"
        try:
            gsha = str(_BUILD_GIT_SHA)
            btime = str(_BUILD_TIME)
        except Exception:
            pass

        # Extract per-horizon Strategy + SPY metrics. The metrics_table is a
        # DataFrame with MultiIndex columns (horizon, series). The series we
        # care about: Strategy and SPY (AUD).
        def _get(metric_name, horizon_label, series_label):
            try:
                return float(metrics_table.loc[metric_name, (horizon_label, series_label)])
            except Exception:
                return None

        horizons = []
        # The horizons depend on what was passed to compute_oos_metrics; cover the
        # standard 3Y / 5Y / 10Y. Skip any horizon that produced no data.
        for hz in ["3Y", "5Y", "10Y"]:
            row = {
                "horizon": hz,
                "strategy_ann_return": _get("Annualised Return", hz, "Strategy"),
                "strategy_sharpe":     _get("Sharpe Ratio",      hz, "Strategy"),
                "strategy_sortino":    _get("Sortino Ratio",     hz, "Strategy"),
                "strategy_max_drawdown": _get("Max Drawdown",    hz, "Strategy"),
                "strategy_alpha_vs_spy": _get("Alpha vs SPY (ann)", hz, "Strategy"),
                "spy_ann_return":     _get("Annualised Return", hz, "SPY (AUD)"),
                "spy_sharpe":         _get("Sharpe Ratio",      hz, "SPY (AUD)"),
                "spy_max_drawdown":   _get("Max Drawdown",      hz, "SPY (AUD)"),
            }
            # Skip horizon if all None (e.g. <3y of data)
            if all(v is None for k, v in row.items() if k != "horizon"):
                continue
            horizons.append(row)

        # Live recommendation snapshot (top 5)
        live_top5 = {}
        try:
            if isinstance(w_ensemble_live, pd.Series) and not w_ensemble_live.empty:
                live_top5 = {str(k): float(v) for k, v in
                              w_ensemble_live.nlargest(5).items()}
        except Exception:
            pass

        # Regime mix snapshot
        live_mix = {}
        try:
            if isinstance(ensemble_mix_live, pd.Series) and not ensemble_mix_live.empty:
                live_mix = {str(k): float(v) for k, v in ensemble_mix_live.items()}
        except Exception:
            pass

        # Optional per-NAV evidence track. Populated when SCALE_SENSITIVITY
        # is on and the scale-sensitivity sweep ran. Strategy-only (SPY
        # is NAV-invariant, already captured in horizons[*].spy_*).
        per_nav_horizons: list[dict] = []
        if scale_metrics:
            for _nav, _mtx in scale_metrics.items():
                if not isinstance(_mtx, pd.DataFrame) or _mtx.empty:
                    continue
                _nav_block: dict = {"nav_aud": float(_nav), "horizons": []}
                for hz in ["3Y", "5Y", "10Y"]:
                    def _gm(metric_name, hz=hz, _mtx=_mtx):
                        try:
                            return float(_mtx.loc[metric_name, (hz, "Strategy")])
                        except Exception:
                            return None
                    _row = {
                        "horizon": hz,
                        "strategy_ann_return": _gm("Annualised Return"),
                        "strategy_sharpe":     _gm("Sharpe Ratio"),
                        "strategy_sortino":    _gm("Sortino Ratio"),
                        "strategy_max_drawdown": _gm("Max Drawdown"),
                        "strategy_alpha_vs_spy": _gm("Alpha vs SPY (ann)"),
                    }
                    if not all(v is None for k, v in _row.items() if k != "horizon"):
                        _nav_block["horizons"].append(_row)
                if _nav_block["horizons"]:
                    per_nav_horizons.append(_nav_block)
            per_nav_horizons.sort(key=lambda b: b["nav_aud"])

        snapshot = {
            "timestamp": pd.Timestamp.now().isoformat(timespec="seconds"),
            "git_sha": gsha,
            "build_time": btime,
            "config": {
                "production_slot_override": (
                    PRODUCTION_SLOT_OVERRIDE if PRODUCTION_SLOT_OVERRIDE else None
                ),
                "production_crash_hedge": bool(PRODUCTION_CRASH_HEDGE),
                "rebalance_freq": REBALANCE_FREQ,
                "skip_rebal_delta": SKIP_REBAL_DELTA,
                "tlh_enabled": TLH_ENABLED,
                "crash_hedge_trigger_dd": CRASH_HEDGE_DD_TRIGGER,
                "crash_hedge_release_dd": CRASH_HEDGE_DD_RELEASE,
                "broker_profile": ACTIVE_BROKER_PROFILE,
                "cgt_profile": ACTIVE_CGT_PROFILE,
            },
            "horizons": horizons,
            "per_nav_horizons": per_nav_horizons,
            "tlh_events": int(tlh_events_n),
            "tlh_loss_realised_aud": float(tlh_loss_aud),
            "n_rebal_executed": int(n_executed),
            "n_rebal_skipped": int(n_skipped),
            "live_regime_mix": live_mix,
            "live_top5_positions": live_top5,
        }

        path = APP_DIR / "metrics_history.jsonl"
        # Read prior snapshot for regression check BEFORE appending.
        prior = None
        try:
            if path.exists():
                with path.open("r", encoding="utf-8") as f:
                    lines = [ln for ln in f if ln.strip()]
                if lines:
                    prior = json.loads(lines[-1])
        except Exception:
            prior = None

        # Append the new snapshot.
        with path.open("a", encoding="utf-8") as f:
            f.write(json.dumps(snapshot) + "\n")
        print(f"[metrics] snapshot → {path}")

        # Regression warnings (10Y horizon is the canonical pitch number).
        if prior:
            cur_10y = next((h for h in horizons if h["horizon"] == "10Y"), None)
            prv_10y = next((h for h in (prior.get("horizons") or [])
                             if h.get("horizon") == "10Y"), None)
            if cur_10y and prv_10y:
                warns = []
                def _d(key, sign=1):
                    cv = cur_10y.get(key); pv = prv_10y.get(key)
                    if cv is None or pv is None:
                        return None
                    return (cv - pv) * sign
                d_sh = _d("strategy_sharpe")
                d_dd = _d("strategy_max_drawdown")  # more negative = worse
                d_al = _d("strategy_alpha_vs_spy")
                if d_sh is not None and d_sh <= -0.10:
                    warns.append(f"10Y Sharpe regressed {d_sh:+.3f} "
                                  f"({prv_10y['strategy_sharpe']:.2f} → {cur_10y['strategy_sharpe']:.2f})")
                if d_dd is not None and d_dd <= -0.05:
                    warns.append(f"10Y MaxDD deepened by {d_dd*100:+.1f}% "
                                  f"({prv_10y['strategy_max_drawdown']*100:+.1f}% → {cur_10y['strategy_max_drawdown']*100:+.1f}%)")
                if d_al is not None and d_al <= -0.01:
                    warns.append(f"10Y α vs SPY worsened by {d_al*100:+.2f}% "
                                  f"({prv_10y['strategy_alpha_vs_spy']*100:+.2f}% → {cur_10y['strategy_alpha_vs_spy']*100:+.2f}%)")
                if warns:
                    print(f"[metrics-warn] REGRESSION vs prior run (git {prior.get('git_sha','?')[:8]} at {prior.get('timestamp','?')[:19]}):")
                    for w in warns:
                        print(f"[metrics-warn]   • {w}")
                else:
                    print(f"[metrics] no material regression vs prior run "
                          f"(git {prior.get('git_sha','?')[:8]} at {prior.get('timestamp','?')[:10]})")
    except Exception as e:
        print(f"[metrics] snapshot write failed: {e}")


def _effective_cgt_rate(short_term: bool = True, cfg: dict | None = None) -> float:
    """Effective tax rate on a $1 of capital gain.
    Short-term: full MTR (+ medicare if enabled).
    Long-term:  full rate × (1 - discount).
    """
    if cfg is None:
        cfg = CGT_CONFIG
    base = float(cfg["marginal_tax_rate"])
    if cfg.get("include_medicare", True):
        base += float(cfg["medicare_levy"])
    if short_term:
        return base
    return base * (1.0 - float(cfg["lt_discount_rate"]))


class LotBook:
    """Tracks FIFO lots per ticker for CGT calculation.

    Each lot stores: acquisition date, units, cost basis per unit.
    On sell: matches oldest lots first (FIFO), classifies each parcel as
    short-term (< 365 days) or long-term, and returns realised gains/losses
    broken down by category. On buy: appends a new lot.
    """
    def __init__(self):
        self.lots: dict[str, list[dict]] = {}

    def buy(self, ticker: str, units: float, date, price: float) -> None:
        if units <= 0 or not np.isfinite(units):
            return
        self.lots.setdefault(ticker, []).append({
            "date": pd.Timestamp(date),
            "units": float(units),
            "cost_basis_per_unit": float(price),
        })

    def sell(self, ticker: str, units: float, date, price: float,
             cfg: dict | None = None) -> dict:
        """FIFO sale. Returns dict with ST/LT realised gain & loss components."""
        if cfg is None:
            cfg = CGT_CONFIG
        lt_threshold = int(cfg["lt_holding_days"])
        out = {"st_gain": 0.0, "lt_gain": 0.0, "st_loss": 0.0, "lt_loss": 0.0}
        if ticker not in self.lots or not self.lots[ticker] or units <= 0:
            return out

        sale_date = pd.Timestamp(date)
        remaining = float(units)
        new_lots = []
        for lot in self.lots[ticker]:
            if remaining <= 1e-9:
                new_lots.append(lot)
                continue
            qty = min(lot["units"], remaining)
            proceeds = qty * float(price)
            cost_base = qty * lot["cost_basis_per_unit"]
            gain = proceeds - cost_base
            hold_days = (sale_date - lot["date"]).days
            is_lt = hold_days >= lt_threshold

            if gain >= 0:
                if is_lt:
                    out["lt_gain"] += gain
                else:
                    out["st_gain"] += gain
            else:
                if is_lt:
                    out["lt_loss"] += -gain
                else:
                    out["st_loss"] += -gain

            remaining -= qty
            if qty < lot["units"]:
                new_lots.append({
                    "date": lot["date"],
                    "units": lot["units"] - qty,
                    "cost_basis_per_unit": lot["cost_basis_per_unit"],
                })

        self.lots[ticker] = new_lots
        return out

    def units(self, ticker: str) -> float:
        """Current units held."""
        return float(sum(lot["units"] for lot in self.lots.get(ticker, [])))

    def unrealised_losses(self, price_snapshot, as_of,
                          min_loss_pct: float = -0.05,
                          min_loss_aud: float = 100.0) -> list[dict]:
        """Return lot-level unrealised losses ≤ min_loss_pct AND ≤ -min_loss_aud.

        Each entry: ticker, lot_idx (within-ticker), units, cost_basis_per_unit,
        current_price, market_value_aud, loss_aud (positive number), loss_pct
        (negative fraction), hold_days. Sorted by largest loss_aud first so the
        TLH pass can prioritise high-value harvests.
        """
        out: list[dict] = []
        ref_date = pd.Timestamp(as_of)
        for tkr, lot_list in self.lots.items():
            try:
                if hasattr(price_snapshot, "get"):
                    p = float(price_snapshot.get(tkr, np.nan))
                else:
                    p = float(price_snapshot[tkr]) if tkr in price_snapshot else float("nan")
            except Exception:
                continue
            if not np.isfinite(p) or p <= 0:
                continue
            for idx, lot in enumerate(lot_list):
                if lot["units"] <= 0:
                    continue
                cost = float(lot["cost_basis_per_unit"])
                mkt = lot["units"] * p
                loss = (cost - p) * lot["units"]  # positive = loss
                if cost <= 0:
                    continue
                loss_pct = (p - cost) / cost     # negative for loss
                if loss_pct > min_loss_pct:      # not loss enough
                    continue
                if loss < min_loss_aud:          # below absolute floor
                    continue
                out.append({
                    "ticker": tkr,
                    "lot_idx": idx,
                    "units": float(lot["units"]),
                    "cost_basis_per_unit": cost,
                    "current_price": p,
                    "market_value_aud": float(mkt),
                    "loss_aud": float(loss),
                    "loss_pct": float(loss_pct),
                    "hold_days": int((ref_date - lot["date"]).days),
                    "lot_date": lot["date"],
                })
        out.sort(key=lambda r: r["loss_aud"], reverse=True)
        return out

    def sell_lot(self, ticker: str, lot_idx: int, units: float, date,
                 price: float, cfg: dict | None = None) -> dict:
        """Sell up to `units` from a SPECIFIC lot (overrides FIFO). Used by the
        TLH pass to target loss lots without disturbing the rest of the book.
        Returns the same realised-bucket dict as `sell()` so callers can fold
        the result straight into the FY accumulators.
        """
        if cfg is None:
            cfg = CGT_CONFIG
        out = {"st_gain": 0.0, "lt_gain": 0.0, "st_loss": 0.0, "lt_loss": 0.0}
        if ticker not in self.lots or units <= 0:
            return out
        lot_list = self.lots[ticker]
        if not (0 <= lot_idx < len(lot_list)):
            return out
        lot = lot_list[lot_idx]
        qty = min(float(lot["units"]), float(units))
        if qty <= 0:
            return out
        lt_threshold = int(cfg["lt_holding_days"])
        proceeds = qty * float(price)
        cost_base = qty * float(lot["cost_basis_per_unit"])
        gain = proceeds - cost_base
        is_lt = (pd.Timestamp(date) - lot["date"]).days >= lt_threshold
        if gain >= 0:
            out["lt_gain" if is_lt else "st_gain"] += gain
        else:
            out["lt_loss" if is_lt else "st_loss"] += -gain
        if qty >= float(lot["units"]) - 1e-9:
            # Removed entirely
            del lot_list[lot_idx]
        else:
            lot["units"] = float(lot["units"]) - qty
        return out


def compute_cgt_for_rebalance(realised: dict, cfg: dict | None = None) -> float:
    """Tax owed on a single rebalance's realised gains, with within-rebalance
    loss offset. Long-term gains discounted before tax. Returns AUD tax.
    """
    if cfg is None:
        cfg = CGT_CONFIG
    st_gain = float(realised.get("st_gain", 0.0))
    lt_gain = float(realised.get("lt_gain", 0.0))
    st_loss = float(realised.get("st_loss", 0.0))
    lt_loss = float(realised.get("lt_loss", 0.0))

    # 1) Net within each category
    st_net = st_gain - st_loss   # may be negative
    lt_net = lt_gain - lt_loss

    # 2) Cross-offset: if one side is negative (net loss), it can reduce the
    #    other side's positive gain. This is the AU rule for the same FY.
    if st_net < 0 and lt_net > 0:
        offset = min(lt_net, -st_net)
        lt_net -= offset
        st_net += offset
    if lt_net < 0 and st_net > 0:
        offset = min(st_net, -lt_net)
        st_net -= offset
        lt_net += offset

    # 3) Apply rates to remaining positive net gains
    tax = 0.0
    if st_net > 0:
        tax += st_net * _effective_cgt_rate(short_term=True, cfg=cfg)
    if lt_net > 0:
        tax += lt_net * _effective_cgt_rate(short_term=False, cfg=cfg)
    return float(tax)


def _run_tlh_pass(
    lot_book: "LotBook",
    price_snapshot,
    as_of,
    cooldown_state: dict,
    pairs: dict | None = None,
    min_loss_pct: float | None = None,
    min_loss_aud: float | None = None,
    cooldown_days: int | None = None,
    cfg: dict | None = None,
    nav_aud: float | None = None,
) -> dict:
    """One pass of tax-loss harvesting. Mutates `lot_book` and `cooldown_state`.

    For each lot in unrealised loss ≥ min_loss_pct (and ≥ min_loss_aud absolute):
      1. Look up its substitute in `pairs`. Skip if no pair, substitute price
         unavailable, or substitute is itself within the cooldown window
         (recently sold via TLH → buying it back here is a wash-swap).
      2. Sell the specific loss lot (realises loss into the FY bucket).
      3. Buy equivalent dollar value of the substitute at current price.
      4. Record the ticker we sold in cooldown_state[ticker] = as_of so it
         can't be the substitute of another TLH swap for cooldown_days.

    Returns dict with:
      events           List of event dicts (date, ticker_sold, lot_date,
                       units_sold, sale_price, cost_basis_per_unit, loss_aud,
                       ticker_bought, units_bought, buy_price, holding).
      realised         {st_gain, lt_gain, st_loss, lt_loss} totals — caller
                       folds into FY accumulator.
      total_loss_aud   Sum of |loss| realised this pass (positive).
      n_events         Count.
    """
    pairs = pairs if pairs is not None else TLH_PAIRS
    min_loss_pct = TLH_MIN_LOSS_PCT if min_loss_pct is None else min_loss_pct
    min_loss_aud = TLH_MIN_LOSS_AUD if min_loss_aud is None else min_loss_aud
    cooldown_days = TLH_COOLDOWN_DAYS if cooldown_days is None else cooldown_days
    as_of_ts = pd.Timestamp(as_of)

    result = {
        "events": [],
        "realised": {"st_gain": 0.0, "lt_gain": 0.0, "st_loss": 0.0, "lt_loss": 0.0},
        "total_loss_aud": 0.0,
        "n_events": 0,
    }
    if not TLH_ENABLED or not pairs:
        return result

    # Take a SNAPSHOT of loss lots first — we mutate the book during the loop
    # (sell_lot deletes/edits entries), so iterating live would be unsafe.
    losses = lot_book.unrealised_losses(
        price_snapshot=price_snapshot,
        as_of=as_of_ts,
        min_loss_pct=min_loss_pct,
        min_loss_aud=min_loss_aud,
    )
    # Re-fetch lot_idx by (ticker, lot_date, cost_basis) at sell time because
    # earlier sells may shift indices within the same ticker.
    def _find_lot_idx(tkr: str, lot_date, cost: float) -> int:
        for i, l in enumerate(lot_book.lots.get(tkr, [])):
            if l["date"] == lot_date and abs(l["cost_basis_per_unit"] - cost) < 1e-9:
                return i
        return -1

    for lossrec in losses:
        tkr = lossrec["ticker"]
        sub = pairs.get(tkr)
        if not sub:
            continue
        # Substitute price must exist + be positive.
        try:
            if hasattr(price_snapshot, "get"):
                p_sub = float(price_snapshot.get(sub, np.nan))
            else:
                p_sub = float(price_snapshot[sub]) if sub in price_snapshot else float("nan")
        except Exception:
            continue
        if not np.isfinite(p_sub) or p_sub <= 0:
            continue
        # Cooldown: substitute can't be a ticker we recently TLH-sold.
        if sub in cooldown_state:
            since = (as_of_ts - pd.Timestamp(cooldown_state[sub])).days
            if since < cooldown_days:
                continue
        # Re-locate the lot (indices may have shifted from earlier sells).
        idx = _find_lot_idx(tkr, lossrec["lot_date"], lossrec["cost_basis_per_unit"])
        if idx < 0:
            continue
        units = lossrec["units"]
        sale_price = lossrec["current_price"]
        sale_value = units * sale_price

        realised = lot_book.sell_lot(
            ticker=tkr, lot_idx=idx, units=units,
            date=as_of_ts, price=sale_price, cfg=cfg,
        )
        for k in result["realised"]:
            result["realised"][k] += realised[k]

        units_bought = sale_value / p_sub
        lot_book.buy(sub, units_bought, as_of_ts, p_sub)
        cooldown_state[tkr] = as_of_ts

        loss_real = float(realised.get("st_loss", 0.0) + realised.get("lt_loss", 0.0))
        result["total_loss_aud"] += loss_real
        result["events"].append({
            "date": as_of_ts,
            "ticker_sold": tkr,
            "lot_date": lossrec["lot_date"],
            "units_sold": float(units),
            "sale_price": float(sale_price),
            "cost_basis_per_unit": float(lossrec["cost_basis_per_unit"]),
            "loss_aud": loss_real,
            "loss_pct": float(lossrec["loss_pct"]),
            "hold_days": int(lossrec["hold_days"]),
            "ticker_bought": sub,
            "units_bought": float(units_bought),
            "buy_price": float(p_sub),
            "swap_value_aud": float(sale_value),
            "nav_aud": float(nav_aud) if nav_aud else None,
        })
        result["n_events"] += 1
    return result


# === Live TLH helpers (Phase 4: trade-plan injection) ========================
# The backtest TLH pass runs inside the walk-forward engine. These helpers
# wrap the same pass for the live pipeline so the recommended trade plan
# already includes harvest swaps and the user executes one atomic batch
# (rebalance + TLH baked in) through Phase 3.
def _build_lot_book_from_df(lots_df: "pd.DataFrame") -> "LotBook":
    """Convert the Lots sheet DataFrame into an in-memory LotBook for TLH/CGT
    queries. Rows with missing/invalid ticker, units, or cost basis are
    skipped silently. Cost basis convention: per-unit AUD (engine standard,
    see _allocate_sale_to_lots)."""
    lb = LotBook()
    if lots_df is None or (hasattr(lots_df, "empty") and lots_df.empty):
        return lb
    for _, r in lots_df.iterrows():
        try:
            tk = str(r.get("Security", "")).strip()
            if not tk or tk.lower() in ("nan", "none"):
                continue
            units = float(r.get("Units", 0) or 0)
            if units <= 0 or not np.isfinite(units):
                continue
            date = pd.Timestamp(r.get("AcqDate"))
            cost_basis = float(r.get("CostBaseAUD", 0) or 0)
            if not np.isfinite(cost_basis) or cost_basis <= 0:
                continue
            lb.buy(tk, units, date, cost_basis)
        except Exception:
            continue
    return lb


def _load_tlh_cooldown_state(path) -> dict:
    """Load persisted TLH cooldown state. Empty dict if file missing/corrupt.
    Stored as {ticker: ISO timestamp string}, returned as {ticker: Timestamp}."""
    try:
        path = Path(path)
        if not path.exists():
            return {}
        with open(path, "r", encoding="utf-8") as f:
            raw = json.load(f)
        return {str(k): pd.Timestamp(v) for k, v in raw.items()}
    except Exception:
        return {}


def _save_tlh_cooldown_state(path, state: dict) -> None:
    """Persist TLH cooldown state to JSON. Failures are logged, not raised —
    the cooldown is an optimisation; a corrupt/missing file just means the
    next run is more cautious (treats no cooldown as active)."""
    try:
        with open(Path(path), "w", encoding="utf-8") as f:
            json.dump({str(k): pd.Timestamp(v).isoformat()
                        for k, v in state.items()}, f, indent=2)
    except Exception as e:
        print(f"[tlh-live] cooldown state save failed: {e}")


def _check_crash_trigger(spy_history, as_of, state: dict,
                          dd_trigger: float | None = None,
                          dd_release: float | None = None,
                          lookback_days: int | None = None) -> bool:
    """Asymmetric crash hedge trigger with hysteresis.

    Enters HEDGE-ON state when SPY peak-to-current drawdown crosses below
    dd_trigger (e.g. -15%). Stays ON until drawdown recovers above
    dd_release (e.g. -5%). The hysteresis prevents whipsaw oscillation
    around the threshold.

    `state` is a mutable dict carried across calls — initial state should
    be `{"active": False}`. The function mutates state["active"] in place
    and also returns the new active flag.

    spy_history: pd.Series of SPY prices, indexed by date.
    as_of: pd.Timestamp — current evaluation date.
    """
    dd_trigger = CRASH_HEDGE_DD_TRIGGER if dd_trigger is None else dd_trigger
    dd_release = CRASH_HEDGE_DD_RELEASE if dd_release is None else dd_release
    lookback_days = CRASH_HEDGE_LOOKBACK_DAYS if lookback_days is None else lookback_days

    if spy_history is None or spy_history.empty:
        return state.get("active", False)
    hist = spy_history.loc[:as_of]
    if hist.empty:
        return state.get("active", False)
    window = hist.tail(lookback_days)
    if window.empty:
        return state.get("active", False)
    rolling_peak = float(window.max())
    current = float(window.iloc[-1])
    if rolling_peak <= 0:
        return state.get("active", False)
    dd = (current - rolling_peak) / rolling_peak  # negative for drawdown

    active = bool(state.get("active", False))
    if not active and dd <= dd_trigger:
        active = True
    elif active and dd >= dd_release:
        active = False
    state["active"] = active
    state["last_dd"] = dd
    return active


def _apply_crash_hedge(weights: pd.Series, basket: dict[str, float] | None = None,
                       available_tickers: pd.Index | None = None) -> pd.Series:
    """Replace `weights` with the crash-hedge basket.

    If a basket ticker isn't in `available_tickers` (e.g. HBRD.AX before
    its 2017 listing), its weight is reallocated proportionally to the
    remaining tickers. Returns a normalised Series indexed like `weights`
    (zero-weight on non-basket tickers).
    """
    basket = CRASH_HEDGE_BASKET if basket is None else basket
    if not basket:
        return weights
    # Filter basket to tickers we actually have data for.
    if available_tickers is not None:
        usable = {k: v for k, v in basket.items() if k in available_tickers}
    else:
        usable = dict(basket)
    if not usable:
        # No basket tickers available — fall back to original weights
        # rather than zero portfolio (defensive against missing data).
        return weights
    total = sum(usable.values())
    if total <= 0:
        return weights
    usable = {k: v / total for k, v in usable.items()}
    # Build a zero series on the original ticker index, then set basket weights.
    out = pd.Series(0.0, index=weights.index)
    for tkr, w in usable.items():
        if tkr in out.index:
            out[tkr] = w
        else:
            # Ticker not in original weight index — extend index
            out[tkr] = w
    # Renormalise (safety against rounding)
    s = out.sum()
    if s > 0:
        out = out / s
    return out


def _is_us_ticker(t) -> bool:
    """A US-listed security: no '.AX' suffix and not an index symbol."""
    s = str(t)
    return not s.endswith(".AX") and not s.startswith("^")


def estimate_rebalance_cost_fraction(
    w_old: pd.Series,
    w_new: pd.Series,
    portfolio_value_aud: float = 1_000_000.0,
    broker_cfg: dict | None = None,
) -> float:
    """Total cost of rebalancing from w_old to w_new, as a FRACTION of NAV.

    Returns e.g. 0.0023 for a 23-bps drag. Subtract this from the realised
    return on the rebalance day to model net-of-cost performance.

    Components:
      1. Fixed per-trade fees (AU $11 etc.) — scaled by NAV (small trades hurt
         small portfolios more, become negligible at scale)
      2. Bid/ask spread cost — bps × trade value (delta weight × NAV)
      3. FX one-way conversion cost — bps × US trade value
    """
    if broker_cfg is None:
        broker_cfg = BROKER_CONFIG

    tickers = sorted(set(w_old.index).union(w_new.index))
    delta = (w_new.reindex(tickers).fillna(0.0) -
             w_old.reindex(tickers).fillna(0.0)).abs()

    n_au_trades = int(sum(1 for t in tickers if delta[t] > 1e-6 and not _is_us_ticker(t)))
    n_us_trades = int(sum(1 for t in tickers if delta[t] > 1e-6 and     _is_us_ticker(t)))
    au_turnover = float(sum(delta[t] for t in tickers if not _is_us_ticker(t)))
    us_turnover = float(sum(delta[t] for t in tickers if     _is_us_ticker(t)))

    # 1. Fixed fees (AUD) as fraction of portfolio
    fixed_cost = (n_au_trades * float(broker_cfg["au_flat_fee_aud"]) +
                  n_us_trades * float(broker_cfg["us_flat_fee_aud"])
                  ) / max(float(portfolio_value_aud), 1.0)

    # 2. Spread costs (decimal)
    spread_cost = (au_turnover * float(broker_cfg["au_spread_bps"]) / 10_000.0 +
                   us_turnover * float(broker_cfg["us_spread_bps"]) / 10_000.0)

    # 3. FX cost (decimal, one-way per US trade)
    fx_cost = us_turnover * float(broker_cfg["fx_spread_bps"]) / 10_000.0

    return float(fixed_cost + spread_cost + fx_cost)


def ask_tradeplan_portfolio_choice() -> str:
    """
    Prompt user to choose between 'ensemble', 'with_tilts' or 'no_tilts'.

    Returns:
        str: "ensemble", "with_tilts" or "no_tilts"
    """
    try:
        import tkinter as tk
        root = tk.Tk()
        root.title("Trade Plan Portfolio")
        # Centre and size the dialog
        root.geometry("420x230")
        root.resizable(False, False)
        choice = {"value": "ensemble"}

        tk.Label(root,
                 text="Which portfolio drives the trade plan?",
                 font=("Arial", 11, "bold")).pack(pady=(18, 8))
        tk.Label(root,
                 text="Ensemble — regime-adaptive blend (recommended)\n"
                      "With Tilts — factor-target portfolio\n"
                      "Optimised — pure max-Sharpe tangency",
                 font=("Arial", 9), justify="left").pack(pady=(0, 12))

        btn = tk.Frame(root)
        btn.pack(pady=4)

        def _pick(val):
            choice["value"] = val
            root.quit()
            root.destroy()

        tk.Button(btn, text="Ensemble", width=12, default="active",
                  command=lambda: _pick("ensemble")).pack(side="left", padx=4)
        tk.Button(btn, text="With Tilts", width=12,
                  command=lambda: _pick("with_tilts")).pack(side="left", padx=4)
        tk.Button(btn, text="Optimised", width=12,
                  command=lambda: _pick("no_tilts")).pack(side="left", padx=4)

        root.protocol("WM_DELETE_WINDOW", lambda: _pick("ensemble"))
        root.mainloop()
        return choice["value"]
    except Exception:
        return "ensemble"  # Safe fallback — ensemble is the recommended live engine


def build_trade_plan_from_units(
    current_units: pd.Series,
    last_prices: pd.Series,
    target_weights: pd.Series,
    cash_buffer: float = 0.0,
    min_trade_aud: float = 0.0,
    round_to_whole_units: bool = True,
    portfolio_value_override: float | None = None
) -> pd.DataFrame:
    """
    Build a rebalance trade list from current units to target weights.

    Args:
        current_units: Current holdings (ticker-indexed).
        last_prices: Latest prices (ticker-indexed).
        target_weights: Target weights (ticker-indexed, sum to 1).
        cash_buffer: Fraction to hold as cash (0-1).
        min_trade_aud: Minimum trade size in AUD.
        round_to_whole_units: Whether to round to whole units.
        portfolio_value_override: Override portfolio value.

    Returns:
        DataFrame with trade plan details.
    """
    # Validate inputs
    if len(target_weights.index) and isinstance(target_weights.index[0], (int, np.integer)):
        raise ValueError("target_weights must be ticker-indexed Series.")

    # Align and clean data
    universe = sorted(set(current_units.index) | set(last_prices.index) | set(target_weights.index))
    u = current_units.reindex(universe).fillna(0.0).astype(float)
    p = last_prices.reindex(universe).fillna(np.nan).astype(float)

    # Filter tradable assets
    tradable = p.notna() & (p > 0) & np.isfinite(p)
    u = u.loc[tradable]
    p = p.loc[tradable]

    w_tgt = target_weights.reindex(u.index).fillna(0.0)

    # Normalize target weights
    w_sum = w_tgt.sum()
    if w_sum > 0:
        w_tgt /= w_sum
    w_tgt *= (1.0 - cash_buffer)

    curr_value = u * p
    port_value = curr_value.sum()

    if portfolio_value_override is not None and np.isfinite(portfolio_value_override) and portfolio_value_override > 0:
        port_value = portfolio_value_override

    if port_value <= 0:
        return pd.DataFrame({
            "Security": u.index,
            "Price": p.values,
            "CurrUnits": u.values,
            "CurrValue": curr_value.values,
            "CurrW": np.zeros(len(u)),
            "TgtW": w_tgt.values,
            "TgtValue": np.zeros(len(u)),
            "DeltaValue": np.zeros(len(u)),
            "TradeUnits": np.zeros(len(u)),
            "Side": ["HOLD"] * len(u),
        })

    curr_w = curr_value / port_value
    tgt_value = w_tgt * port_value
    delta_value = tgt_value - curr_value
    trade_units = delta_value / p

    if round_to_whole_units:
        trade_units = np.where(trade_units >= 0, np.floor(trade_units), np.ceil(trade_units))

    # Apply min trade filter
    notional = np.abs(trade_units * p)
    trade_units = np.where(notional >= min_trade_aud, trade_units, 0.0)

    side = np.where(trade_units > 0, "BUY", np.where(trade_units < 0, "SELL", "HOLD"))

    out = pd.DataFrame({
        "Security": u.index,
        "Price": p.values,
        "CurrUnits": u.values,
        "CurrValue": curr_value.values,
        "CurrW": curr_w.values,
        "TgtW": w_tgt.values,
        "TgtValue": tgt_value.values,
        "DeltaValue": delta_value.values,
        "TradeUnits": trade_units,
        "Side": side
    })

    # Sort: sells first, then buys
    side_rank = {"SELL": 0, "HOLD": 1, "BUY": 2}
    out["SideRank"] = out["Side"].map(side_rank).fillna(1).astype(int)
    out = out.sort_values(["SideRank", "Security"]).drop(columns=["SideRank"]).reset_index(drop=True)

    return out


# NOTE: _annualized_sharpe moved to metrics.py (Phase 4 split).


def choose_portfolio_for_tradeplan(
    returns_df: pd.DataFrame,
    w_no_tilts: pd.Series,
    w_with_tilts: pd.Series,
    rf_annual: float,
    lookback_days: int = VALIDATION_LOOKBACK_DAYS,
    w_ensemble: pd.Series | None = None,
) -> tuple[str, pd.Series, dict]:
    """
    Choose portfolio based on Sharpe ratio over lookback period.
    With w_ensemble provided, compares THREE candidates and picks the highest
    Sharpe — typically the ensemble wins because it's regime-adaptive.

    Returns:
        (choice, weights, diagnostics)
    """
    r = returns_df.tail(lookback_days).replace([np.inf, -np.inf], np.nan).dropna(how="all")

    w0 = w_no_tilts.reindex(r.columns).fillna(0.0)
    w1 = w_with_tilts.reindex(r.columns).fillna(0.0)
    we = (w_ensemble.reindex(r.columns).fillna(0.0)
          if isinstance(w_ensemble, pd.Series) and not w_ensemble.empty
          else None)

    # Normalize weights
    for w in [w0, w1]:
        w_sum = w.sum()
        if w_sum != 0:
            w /= w_sum
    if we is not None:
        we_sum = we.sum()
        if we_sum != 0:
            we /= we_sum

    p0 = (r @ w0).dropna()
    p1 = (r @ w1).dropna()
    pe = (r @ we).dropna() if we is not None else pd.Series(dtype=float)

    sh0 = _annualized_sharpe(p0, rf_annual)
    sh1 = _annualized_sharpe(p1, rf_annual)
    she = _annualized_sharpe(pe, rf_annual) if not pe.empty else np.nan

    diag = {"sharpe_no_tilts": sh0, "sharpe_with_tilts": sh1, "sharpe_ensemble": she}

    candidates = []
    if np.isfinite(she) and we is not None:
        candidates.append(("ensemble", we, she))
    if np.isfinite(sh1):
        candidates.append(("with_tilts", w1, sh1))
    if np.isfinite(sh0):
        candidates.append(("no_tilts", w0, sh0))

    if not candidates:
        return "no_tilts", w0, diag
    # Stable sort: highest Sharpe wins, ties broken by entry order (ensemble first).
    candidates.sort(key=lambda x: x[2], reverse=True)
    choice, w_chosen, _ = candidates[0]
    return choice, w_chosen, diag

