def _normalize_yfinance_close(dl) -> pd.DataFrame:
    """Handle yfinance output (may be Series or DataFrame) and return DataFrame."""
    if isinstance(dl, pd.DataFrame) and "Close" in dl.columns:
        return dl["Close"]
