OPEN_EXCEL_AFTER_SAVE = bool(globals().get("OPEN_EXCEL_AFTER_SAVE", CFG.get("open_excel_after_save", True)))
OPEN_PPT_AFTER_SAVE = bool(globals().get("OPEN_PPT_AFTER_SAVE", CFG.get("open_ppt_after_save", True)))

